SELECT NU_ANO_CENSO
FROM matriculas
WHERE NU_ANO_CENSO IS NOT NULL AND TRIM(NU_ANO_CENSO) = '2025';

SELECT DICIONARIO: NU_ANO_CENSO
FROM matriculas
WHERE NU_ANO_CENSO = 2025;

SELECT DICIONARIO: NU_ANO_CENSO
FROM matriculas
WHERE NU_ANO_CENSO = (SELECT MIN(NU_ANO_CENSO) FROM matriculas);

SELECT * 
FROM matriculas 
WHERE QT_MAT_BAS = 0;

SELECT QT_MAT_BAS
FROM matriculas
WHERE QT_MAT_BAS = 0;

SELECT DICIONARIO: CO_REDE, DICIONARIO: TP_DEPENDENCIA
FROM matriculas
WHERE CO_ENTIDADE IS NOT NULL;

SELECT SUM(QT_MAT_BAS) AS total_matriculas_municipal, AVG(QT_MAT_BAS) AS media_matriculas_municipal
FROM matriculas
WHERE CO_ENTIDADE IN (SELECT CO_ENTIDADE FROM CO_REDE WHERE CO_REDE LIKE '%MUNICIPAL%');

SELECT SUM(QT_MAT_BAS) AS total_matriculas_estadual, AVG(QT_MAT_BAS) AS media_matriculas_estadual
FROM matriculas
WHERE CO_ENTIDADE IN (SELECT CO_ENTIDADE FROM CO_REDE WHERE CO_REDE LIKE '%ESTADUAL%');

SELECT DICIONARIO: IN_PODER_PUBLICO_PARCERIA
FROM matriculas
WHERE IN_PODER_PUBLICO_PARCERIA = 1;

SELECT DICIONARIO: IN_PODER_PUBLICO_PARCERIA
FROM matriculas
WHERE IN_PODER_PUBLICO_PARCERIA = '1';

SELECT IN_PODER_PUBLICO_PARCERIA 
FROM matriculas 
WHERE IN_PODER_PUBLICO_PARCERIA = 1;

SELECT COUNT(DISTINCT CO_ENTIDADE) 
FROM matriculas 
WHERE IN_PODER_PUBLICO_PARCERIA = 1;

SELECT COUNT(DISTINCT CO_ENTIDADE) AS num_escolas_urbanas, COUNT(DISTINCT CO_ENTIDADE) AS num_escolas_rurais
FROM matriculas
WHERE TRIM(NO_REGIAO) = 'URB' OR TRIM(NO_REGIAO) = 'RUR';

SELECT COUNT(DISTINCT CO_ENTIDADE) AS URBAN_SCHOOLS, SUM(QT_MAT_BAS) AS RURAL_SCHOOLS
FROM matriculas
WHERE TP_LOCALIZACAO = '2' AND CO_REGIAO_GEOG_INTERM IS NOT NULL;

SELECT SUM(CASE WHEN TP_LOCALIZACAO = '2' THEN 1 ELSE 0 END) AS ESCOLAS_URBANAS,
       SUM(CASE WHEN TP_LOCALIZACAO = '3' THEN 1 ELSE 0 END) AS ESCOLAS_RURALS
FROM matriculas;

SELECT SUM(CASE WHEN TP_LOCALIZACAO = '2' THEN 1 ELSE 0 END) AS TOTAL_ESCOLAS_URBANAS,
       SUM(CASE WHEN TP_LOCALIZACAO = '3' THEN 1 ELSE 0 END) AS TOTAL_ESCOLAS_RURALS
FROM matriculas;

SELECT SUM(CASE WHEN TP_LOCALIZACAO = '2' THEN 1 ELSE 0 END) AS total_escolas_urbana, 
       SUM(CASE WHEN TP_LOCALIZACAO = '1' THEN 1 ELSE 0 END) AS total_escolas_rural 
FROM matriculas;

SELECT SUM(CASE WHEN TP_LOCALIZACAO = '2' THEN QT_MAT_BAS ELSE 0 END) AS total_escolas_urbanas, 
       SUM(CASE WHEN TP_LOCALIZACAO = '1' THEN QT_MAT_BAS ELSE 0 END) AS total_escolas_rurais
FROM matriculas;

SELECT SUM(QT_MAT_BAS) AS total_matriculas
FROM matriculas
WHERE CO_ENTIDADE IN ('Educação Infantil', 'Ensino Fundamental', 'Ensino Médio', 'Educação Profissional', 'EJA');

SELECT 
  (SUM(QT_MAT_FUND_AI) - SUM(QT_MAT_FUND_AF)) / SUM(QT_MAT_FUND_AI) * 100 AS porcentagem_diferença
FROM matriculas;

SELECT 
  DICIONARIO: QT_MAT_PROF_TEC
FROM matriculas;

SELECT 
  DICIONARIO: QT_MAT_PROF_TEC AS total_matrículas_profissional_técnica
FROM matriculas;

SELECT SUM(QT_MAT_PROF_TEC) AS total_profissional_tecnica,
       100 * SUM(QT_MAT_PROF_TEC) / SUM(QT_MAT_BAS) AS percentual_profissional_tecnica
FROM matriculas;

SELECT SUM(QT_MAT_PROF_TEC), 
       SUM(QT_MAT_PROF_TEC) / SUM(QT_MAT_BAS) * 100 AS PERCENTUAL 
FROM matriculas;

SELECT SUM(QT_MAT_EJA_MED_D), SUM(QT_MAT_EJA_D), COUNT(DISTINCT CO_ENTIDADE)
FROM matriculas
WHERE QT_MAT_EJA_MED_D > 0 AND QT_MAT_EJA_D > 0;

SELECT QT_MAT_EJA_MED_D, QT_MAT_EJA_D, COUNT(DISTINCT CO_ENTIDADE)
FROM matriculas
WHERE QT_MAT_EJA_MED_D > 0 AND QT_MAT_EJA_D > 0;

SELECT SUM(QT_MAT_BAS_LIBRAS) AS total_nacional
FROM matriculas
WHERE QT_MAT_BAS_LIBRAS > 0;

SELECT 100.0 * SUM(QT_MAT_BAS_BRANCA) / SUM(QT_MAT_BAS)
FROM matriculas
WHERE QT_MAT_BAS_BRANCA > 0 AND QT_MAT_BAS_BRANCA IS NOT NULL;

SELECT SUM(QT_MAT_BAS_BRANCA) + SUM(QT_MAT_BAS_PRETA) AS TOTAL_DE_MATRICULAS_BRANCA
FROM matriculas
WHERE QT_MAT_BAS_BRANCA + QT_MAT_BAS_PRETA + QT_MAT_BAS_PARDA + QT_MAT_BAS_AMARELA + QT_MAT_BAS_INDIGENA > 0;

SELECT SUM(QT_MAT_BAS_BRANCA) + SUM(QT_MAT_BAS_PRETA) AS TOTAL_DE_MATRICULAS_BRANCA
FROM matriculas
WHERE QT_MAT_BAS_BRANCA + QT_MAT_BAS_PRETA + QT_MAT_BAS_PARDA + QT_MAT_BAS_AMARELA + QT_MAT_BAS_INDIGENA > 0 AND QT_MAT_BAS_BRANCA + QT_MAT_BAS_PRETA + QT_MAT_BAS_PARDA + QT_MAT_BAS_AMARELA + QT_MAT_BAS_INDIGENA < (QT_MAT_BAS_BRANCA + QT_MAT_BAS_PRETA + QT_MAT_BAS_PARDA + QT_MAT_BAS_AMARELA + QT_MAT_BAS_INDIGENA);

SELECT SUM(QT_MAT_BAS_BRANCA) AS TOTAL_DE_MATRICULAS_BRANCA
FROM matriculas
WHERE QT_MAT_BAS_BRANCA + QT_MAT_BAS_PRETA + QT_MAT_BAS_PARDA + QT_MAT_BAS_AMARELA + QT_MAT_BAS_INDIGENA > 0;

SELECT SUM(QT_MAT_BAS_ND) AS total_matrículas_nd
FROM matriculas
WHERE QT_MAT_BAS_ND > 0;

SELECT COUNT(DISTINCT CO_ENTIDADE)
FROM matriculas
WHERE QT_MAT_BAS > 0 AND QT_MAT_MED_1 + QT_MAT_MED_2 + QT_MAT_MED_3 > 0;

SELECT 'D' AS TURNO, SUM(QT_MAT_BAS) AS TOTAL_MATRICULAS
FROM matriculas
GROUP BY 'D';

SELECT SUM(QT_MAT_BAS) AS total_matrículas
FROM matriculas
WHERE TP_LOCALIZACAO = '2' AND TRIM(QT_MAT_BAS) > 0;

SELECT SUM(QT_MAT_BAS_INT) AS total_matriculas_integrals, 
       (SUM(QT_MAT_BAS) / SUM(QT_MAT_BAS)) * 100 AS percentual_matriculas_integrals
FROM matriculas;

SELECT QT_MAT_ESP_CC, QT_MAT_ESP_CC_INF, (QT_MAT_ESP_CC + QT_MAT_ESP_CC_INF) / (QT_MAT_ESP_CC + QT_MAT_ESP_CC_INF) * 100 AS PORCENTAGEM
FROM matriculas
WHERE QT_MAT_ESP_CC IS NOT NULL AND QT_MAT_ESP_CC_INF IS NOT NULL;

SELECT (SUM(QT_MAT_ESP_CC) + SUM(QT_MAT_ESP_CE)) / (SUM(QT_MAT_ESP_CC) + SUM(QT_MAT_ESP_CE)) * 100 AS PORCENTAGEM
FROM matriculas
WHERE QT_MAT_ESP_CC IS NOT NULL AND QT_MAT_ESP_CE IS NOT NULL;
